import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { HealthService } from '../../services/health.service';
import { HealthData } from '../../models/health-data.model';

@Component({
  selector: 'app-upload',
  templateUrl: './upload.component.html',
  styleUrls: ['./upload.component.scss']
})
export class UploadComponent implements OnInit {
  uploadForm: FormGroup;
  selectedFile: File | null = null;
  previewUrl: string | null = null;
  isUploading = false;

  constructor(
    private fb: FormBuilder,
    private healthService: HealthService,
    private router: Router
  ) {
    this.uploadForm = this.fb.group({
      username: ['', [Validators.required, Validators.minLength(2)]]
    });
  }

  ngOnInit(): void {
  }

  onFileSelected(event: any): void {
    const file = event.target.files[0];
    if (file) {
      this.selectedFile = file;
      
      // Create preview URL
      const reader = new FileReader();
      reader.onload = (e: any) => {
        this.previewUrl = e.target.result;
      };
      reader.readAsDataURL(file);
    }
  }

  onSubmit(): void {
    if (this.uploadForm.valid && this.selectedFile) {
      this.isUploading = true;
      const username = this.uploadForm.get('username')?.value;

      this.healthService.uploadImage(this.selectedFile, username).subscribe({
        next: (data: HealthData) => {
          this.isUploading = false;
          this.router.navigate(['/dashboard'], { 
            state: { 
              data: data, 
              username: username,
              isNewUpload: true 
            } 
          });
        },
        error: (error) => {
          console.error('Upload error:', error);
          this.isUploading = false;
          alert('Failed to upload image. Please try again.');
        }
      });
    }
  }

  goBack(): void {
    this.router.navigate(['/']);
  }
}
<div class="min-h-screen flex flex-col">
  <app-header></app-header>
  
  <main class="flex-1 px-4 py-6">
    <!-- Header -->
    <div class="flex items-center mb-6">
      <button 
        (click)="goBack()"
        class="p-2 rounded-xl hover:bg-white/20 transition-colors mr-3">
        <svg class="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/>
        </svg>
      </button>
      <h1 class="text-2xl font-bold text-white">Upload Today's Data</h1>
    </div>

    <!-- Upload Form -->
    <div class="card">
      <form [formGroup]="uploadForm" (ngSubmit)="onSubmit()" class="space-y-6">
        <!-- Username Input -->
        <div>
          <label class="block text-sm font-semibold text-dark-blue mb-2">
            Username
          </label>
          <input
            type="text"
            formControlName="username"
            class="input-field"
            placeholder="Enter your username"
            [class.border-red-500]="uploadForm.get('username')?.invalid && uploadForm.get('username')?.touched"
          />
          <div *ngIf="uploadForm.get('username')?.invalid && uploadForm.get('username')?.touched" 
               class="text-red-500 text-sm mt-1">
            Username is required and must be at least 2 characters
          </div>
        </div>

        <!-- File Upload -->
        <div>
          <label class="block text-sm font-semibold text-dark-blue mb-2">
            Fitness App Screenshot
          </label>
          <div class="border-2 border-dashed border-grey/50 rounded-xl p-6 text-center hover:border-cyan transition-colors">
            <input
              type="file"
              id="imageUpload"
              accept="image/*"
              (change)="onFileSelected($event)"
              class="hidden"
            />
            <label for="imageUpload" class="cursor-pointer">
              <div *ngIf="!previewUrl; else previewTemplate" class="space-y-4">
                <div class="w-16 h-16 bg-cyan/20 rounded-2xl flex items-center justify-center mx-auto">
                  <svg class="w-8 h-8 text-cyan" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/>
                  </svg>
                </div>
                <div>
                  <p class="text-lg font-medium text-dark-blue">Upload your fitness screenshot</p>
                  <p class="text-sm text-grey">PNG, JPG, or JPEG up to 10MB</p>
                </div>
              </div>
              
              <ng-template #previewTemplate>
                <div class="space-y-4">
                  <img
                    [src]="previewUrl"
                    alt="Preview"
                    class="max-h-48 mx-auto rounded-xl shadow-lg"
                  />
                  <p class="text-sm text-grey">Tap to change image</p>
                </div>
              </ng-template>
            </label>
          </div>
        </div>

        <!-- Submit Button -->
        <button
          type="submit"
          [disabled]="!uploadForm.valid || !selectedFile || isUploading"
          class="w-full btn-primary text-lg py-4 flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <div *ngIf="isUploading; else uploadText" class="flex items-center space-x-2">
            <svg class="animate-spin w-5 h-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
              <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
            <span>Analyzing...</span>
          </div>
          
          <ng-template #uploadText>
            <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/>
            </svg>
            <span>Analyze Screenshot</span>
          </ng-template>
        </button>
      </form>
    </div>

    <!-- Tips -->
    <div class="mt-8 card">
      <h3 class="text-lg font-semibold text-dark-blue mb-4">Tips for Best Results</h3>
      <div class="space-y-3">
        <div class="flex items-start space-x-3">
          <div class="w-6 h-6 bg-cyan/20 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
            <span class="text-cyan text-xs font-bold">1</span>
          </div>
          <p class="text-sm text-grey">Make sure the screenshot is clear and well-lit</p>
        </div>
        <div class="flex items-start space-x-3">
          <div class="w-6 h-6 bg-cyan/20 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
            <span class="text-cyan text-xs font-bold">2</span>
          </div>
          <p class="text-sm text-grey">Include the main dashboard view with steps and calories visible</p>
        </div>
        <div class="flex items-start space-x-3">
          <div class="w-6 h-6 bg-cyan/20 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
            <span class="text-cyan text-xs font-bold">3</span>
          </div>
          <p class="text-sm text-grey">Upload daily to track your progress over time</p>
        </div>
      </div>
    </div>
  </main>
</div>
